        sw = sum(ws)
        pred_resid = sum(w * nxt for w, (dd, nxt, s) in zip(ws, donors)) / sw
    else:
        pred_resid = 0.0
    xnew = [(series[b][n - 1] - means[j]) / stds[j] for j, b in enumerate(bands)]
    base = ridge_pred(coef, xnew)
    pred = base + pred_resid
    rmse = math.sqrt(sum(r * r for r in resid[1:]) / len(resid[1:]))
    ymean = sum(y) / len(y)
    ystd = math.sqrt(sum((v - ymean) ** 2 for v in y) / len(y))
    nrmse = rmse / ystd if ystd > 1e-12 else 0.0
    return pred, nrmse, donors, base, pred_resid

def diff_series(series, bands):
    return {b: [series[b][i] - series[b][i - 1] for i in range(1, len(series[b]))] for b in bands}

def main():
    bands, times, panel = load_panel("data.csv")
    series = {b: [panel[b][t] for t in times] for b in bands}
    L = 2
    lam = 1.0
    ds = diff_series(series, bands)
    out = {}
    diag = []
    for b in bands:
        pl, nl, dl, bl, prl = forecast_band(series, bands, b, L, lam)
        pd_, nd, dd, bd, prd = forecast_band(ds, bands, b, L, lam)
        pdiff = series[b][-1] + pd_
        if nd < nl:
            pred, transform, nrmse, donors = pdiff, "difference", nd, dd
        else:
            pred, transform, nrmse, donors = pl, "level", nl, dl
        out[b] = pred
        diag.append({"band": b, "level_pred": round(pl, 6), "diff_pred": round(pdiff, 6),
                     "chosen": transform, "level_nrmse": round(nl, 4), "diff_nrmse": round(nd, 4),
                     "donors": [(round(d, 6), round(nx, 6), s) for d, nx, s in donors]})
    print(json.dumps(diag, indent=2))
    print("PRED", json.dumps({k: round(v, 6) for k, v in out.items()}, indent=2))

main()
